<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
$id=max(0,(int)($_GET['id']??$_POST['siswa_id']??0));$siswa=siswa_find($pdo,$id);if(!$siswa){http_response_code(404);exit('Siswa tidak ditemukan.');}
$errors=[];$success='';
$years=$pdo->query('SELECT id,nama,aktif FROM tahun_pelajaran ORDER BY id DESC')->fetchAll();$classes=$pdo->query('SELECT id,nama,tingkat FROM master_kelas WHERE aktif=1 ORDER BY tingkat,nama')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$year=(int)($_POST['tahun_pelajaran_id']??0);$class=(int)($_POST['kelas_id']??0);$ket=trim((string)($_POST['keterangan']??''));$year_ids=array_map('intval',array_column($years,'id'));$class_ids=array_map('intval',array_column($classes,'id'));if(!in_array($year,$year_ids,true))$errors[]='Tahun pelajaran tidak valid.';if(!in_array($class,$class_ids,true))$errors[]='Kelas tidak valid.';if(!$errors){$pdo->beginTransaction();try{$lock=$pdo->prepare('SELECT id,kelas_id,status FROM siswa_kelas WHERE siswa_id=? AND tahun_pelajaran_id=? AND status="aktif" ORDER BY id DESC LIMIT 1 FOR UPDATE');$lock->execute([$id,$year]);$current=$lock->fetch();if($current && (int)$current['kelas_id']===$class){$errors[]='Siswa sudah berada di kelas tersebut.';$pdo->rollBack();}else{if($current){$up=$pdo->prepare("UPDATE siswa_kelas SET status='pindah' WHERE id=?");$up->execute([(int)$current['id']]);}$ins=$pdo->prepare("INSERT INTO siswa_kelas (siswa_id,tahun_pelajaran_id,kelas_id,nomor_urut,status,keterangan) VALUES (?,?,?,?, 'aktif',NULLIF(?,''))");$numSt=$pdo->prepare("SELECT COALESCE(MAX(nomor_urut),0)+1 FROM siswa_kelas WHERE tahun_pelajaran_id=? AND kelas_id=? AND status='aktif'");$numSt->execute([$year,$class]);$nomor=(int)$numSt->fetchColumn();$ins->execute([$id,$year,$class,$nomor,$ket]);$new=(int)$pdo->lastInsertId();$pdo->commit();siswa_audit($pdo,'CLASS_ASSIGN',$id,'Penempatan/perpindahan kelas, siswa_kelas #'.$new);$success='Penempatan kelas berhasil disimpan.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
$st=$pdo->prepare("SELECT sk.*,mk.nama nama_kelas,tp.nama tahun_nama FROM siswa_kelas sk JOIN master_kelas mk ON mk.id=sk.kelas_id JOIN tahun_pelajaran tp ON tp.id=sk.tahun_pelajaran_id WHERE sk.siswa_id=? ORDER BY tp.id DESC,sk.id DESC");$st->execute([$id]);$history=$st->fetchAll();
$page_title='Riwayat Kelas';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Riwayat Kelas</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Kelas: <?=e($siswa['nama'])?></h1><p>NIS <?=e($siswa['nis'])?>. Setiap perpindahan disimpan sebagai riwayat.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>siswa/detail.php?id=<?=$id?>">Kembali</a></div><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="form-card"><div class="section-title"><div><h2>Tempatkan / Pindahkan</h2><p>Jika tahun pelajaran sama dan kelas berbeda, kelas lama otomatis menjadi <strong>pindah</strong>.</p></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="siswa_id" value="<?=$id?>"><div class="form-grid"><label>Tahun Pelajaran *<select class="form-control" name="tahun_pelajaran_id" required><option value="">- Pilih -</option><?php foreach($years as $y):?><option value="<?=$y['id']?>" <?=$y['aktif']?'selected':''?>><?=e($y['nama'])?><?=$y['aktif']?' (aktif)':''?></option><?php endforeach;?></select></label><label>Kelas *<select class="form-control" name="kelas_id" required><option value="">- Pilih -</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['nama'])?></option><?php endforeach;?></select></label><label style="grid-column:1/-1">Keterangan<input class="form-control" name="keterangan" placeholder="Contoh: pindah dari 8A ke 8B"></label></div><div class="form-actions"><button class="btn btn-primary">Simpan Penempatan</button></div></form></div><div class="dashboard-table-card"><div class="section-title"><div><h2>Riwayat Penempatan</h2></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Tahun</th><th>Kelas</th><th>No.</th><th>Status</th><th>Keterangan</th><th>Dibuat</th></tr></thead><tbody><?php if(!$history):?><tr><td colspan="5" class="empty-state">Belum ada penempatan kelas.</td></tr><?php else:foreach($history as $r):?><tr><td><?=e($r['tahun_nama'])?></td><td><?=e($r['nama_kelas'])?></td><td><?= $r['nomor_urut']!==null?(int)$r['nomor_urut']:'-' ?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e((string)($r['keterangan']??'-'))?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php'; ?>
